/**
 * Sound effects made in code: no audio files, no downloads, nothing generated by an AI tool. Each effect is a
 * small recipe of tones and filtered noise (the same kind of synthesis as `synth.ts` and the film music in
 * `studio/scripts/music.mjs`), rendered to plain samples. The same recipes serve the films (mixed in Node by
 * `mix.ts` and muxed into the MP4) and the site (played through `synth.ts`).
 *
 * Everything is deterministic: an effect with the same options and seed is the same samples on every machine.
 * Plain TypeScript with no imports, so Node can load this file directly.
 */
export const SR = 48000

function rng(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
const buf = (sec: number) => new Float32Array(Math.max(1, Math.round(sec * SR)))
/** Adds a tone whose pitch glides from f0 to f1 and whose loudness dies away over `tau` seconds. */
function tone(out: Float32Array, at: number, f0: number, f1: number, dur: number, tau: number, amp: number, attack = 0.004, harm = 0) {
  const s = Math.round(at * SR)
  const n = Math.min(out.length - s, Math.round(dur * SR))
  let ph = 0
  for (let i = 0; i < n; i++) {
    const u = i / n
    const f = f0 * Math.pow(f1 / f0, u)
    ph += (2 * Math.PI * f) / SR
    const env = Math.min(1, i / (attack * SR)) * Math.exp(-i / (tau * SR)) * Math.min(1, (n - i) / (0.004 * SR))
    out[s + i] += (Math.sin(ph) + harm * Math.sin(2 * ph) + harm * 0.5 * Math.sin(3 * ph)) * env * amp
  }
}
/** Adds a burst of noise through a band-pass filter that can sweep from `fa` to `fb`. `q` is how narrow the band is. */
function hiss(out: Float32Array, r: () => number, at: number, dur: number, fa: number, fb: number, q: number, amp: number, shape: (u: number) => number) {
  const s = Math.round(at * SR)
  const n = Math.min(out.length - s, Math.round(dur * SR))
  let lo = 0
  let band = 0
  for (let i = 0; i < n; i++) {
    const u = i / n
    const fc = fa * Math.pow(fb / fa, u)
    const f = 2 * Math.sin((Math.PI * Math.min(fc, SR / 6.5)) / SR)
    const x = r() * 2 - 1
    const hi = x - lo - q * band
    band += f * hi
    lo += f * band
    out[s + i] += band * shape(u) * amp
  }
}
const decay = (k: number) => (u: number) => Math.min(1, u * 60) * Math.exp(-u * k)
const swell = (p = 1.6) => (u: number) => Math.pow(Math.sin(Math.PI * u), p)
function lowpass(x: Float32Array, fc: number): Float32Array {
  const k = 1 - Math.exp((-2 * Math.PI * fc) / SR)
  let y = 0
  for (let i = 0; i < x.length; i++) {
    y += k * (x[i] - y)
    x[i] = y
  }
  return x
}
function peakTo(x: Float32Array, level: number): Float32Array {
  let m = 1e-9
  for (let i = 0; i < x.length; i++) m = Math.max(m, Math.abs(x[i]))
  for (let i = 0; i < x.length; i++) x[i] *= level / m
  return x
}

export type Ground = 'stone' | 'wood' | 'grass' | 'sand' | 'rug'
export type SfxOpts = { seed?: number; /** Seconds, for the effects that last (rain, wind, birds, bee). */ dur?: number; ground?: Ground; /** 0 light (a child, a cat) … 1 heavy. */ weight?: number; /** Pitch, as a multiple of the effect's own. */ pitch?: number; /** How many (knocks, claps, laughs). */ count?: number }

/**
 * The library. Every effect returns mono samples at 48 kHz with its loudest moment near full scale; the mixer
 * sets how loud it is in the film.
 */
export const SFX = {
  /** One footstep: a heel and the ball of the foot, on stone, wood, grass, sand or a rug. */
  step(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 1)
    const w = o.weight ?? 0.6
    const g = o.ground ?? 'stone'
    const out = buf(0.34)
    const j = 0.9 + r() * 0.2
    if (g === 'stone') {
      tone(out, 0, 120 * j, 70, 0.09, 0.03, 0.5 + 0.5 * w)
      hiss(out, r, 0, 0.03, 2600 * j, 1500, 0.7, 0.5, decay(9))
      hiss(out, r, 0.055 + 0.02 * w, 0.035, 1800 * j, 1200, 0.8, 0.26, decay(8))
    } else if (g === 'wood') {
      tone(out, 0, 170 * j, 120, 0.2, 0.06, 0.6 + 0.4 * w)
      tone(out, 0, 330 * j, 300, 0.1, 0.03, 0.3)
      tone(out, 0.002, 520 * j, 500, 0.07, 0.02, 0.16)
      hiss(out, r, 0, 0.02, 2000, 1400, 0.9, 0.3, decay(9))
      tone(out, 0.06, 150 * j, 110, 0.14, 0.04, 0.3 * w)
    } else if (g === 'grass') {
      hiss(out, r, 0, 0.16, 2400 * j, 1100, 1.2, 0.8, (u) => Math.min(1, u * 14) * Math.exp(-u * 4.5) * (0.6 + 0.4 * Math.sin(u * 60)))
      hiss(out, r, 0.05, 0.14, 5200, 3000, 1.3, 0.3, decay(5))
      tone(out, 0, 90, 60, 0.07, 0.03, 0.3 * w)
    } else if (g === 'sand') {
      hiss(out, r, 0, 0.2, 3800 * j, 1800, 1.1, 0.8, (u) => Math.min(1, u * 10) * Math.exp(-u * 3.4) * (r() > 0.35 ? 1 : 0.3))
      hiss(out, r, 0.07, 0.16, 6500, 4200, 1.2, 0.3, (u) => Math.exp(-u * 4) * (r() > 0.5 ? 1 : 0.2))
    } else {
      tone(out, 0, 100 * j, 62, 0.11, 0.045, 0.7 + 0.3 * w)
      hiss(out, r, 0, 0.05, 700, 400, 1.2, 0.3, decay(7))
    }
    return peakTo(out, 0.9)
  },
  /** The tip of a walking stick set down on hard ground. */
  cane(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 3)
    const out = buf(0.22)
    const j = (o.pitch ?? 1) * (0.94 + r() * 0.12)
    tone(out, 0, 980 * j, 900 * j, 0.06, 0.016, 0.7)
    tone(out, 0, 1760 * j, 1650 * j, 0.04, 0.01, 0.35)
    tone(out, 0, 210, 150, 0.08, 0.03, 0.4)
    hiss(out, r, 0, 0.012, 3200, 2400, 0.8, 0.4, decay(8))
    return peakTo(out, 0.9)
  },
  /** A wooden door: the creak of its hinge, then the latch. */
  door(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 5)
    const out = buf(1.25)
    // the creak: a stick-slip buzz that climbs, heard through two resonances of the wood
    const creak = buf(0.8)
    let ph = 0
    for (let i = 0; i < creak.length; i++) {
      const u = i / creak.length
      const f = (34 + 60 * u * u + 6 * Math.sin(u * 40)) * (o.pitch ?? 1)
      ph += f / SR
      const p = ph - Math.floor(ph)
      creak[i] = (p < 0.12 ? 1 - p / 0.12 : 0) * Math.sin(Math.PI * u) * (0.7 + 0.3 * r())
    }
    for (const [fc, a] of [[620, 1], [1480, 0.6], [2700, 0.25]] as const) {
      let lo = 0
      let band = 0
      const f = 2 * Math.sin((Math.PI * fc) / SR)
      for (let i = 0; i < creak.length; i++) {
        const hi = creak[i] - lo - 0.12 * band
        band += f * hi
        lo += f * band
        out[i] += band * a * 0.5
      }
    }
    tone(out, 0.9, 150, 84, 0.2, 0.06, 0.9)
    tone(out, 0.9, 420, 380, 0.07, 0.02, 0.3)
    hiss(out, r, 0.9, 0.03, 2400, 1500, 0.8, 0.5, decay(9))
    return peakTo(out, 0.9)
  },
  /** Knuckles on a door: three knocks unless `count` says otherwise. */
  knock(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 7)
    const n = o.count ?? 3
    const out = buf(0.18 * n + 0.3)
    for (let i = 0; i < n; i++) {
      const at = i * 0.17 + (r() - 0.5) * 0.012
      const j = (o.pitch ?? 1) * (0.96 + r() * 0.08)
      const a = i === 0 ? 1 : 0.8
      tone(out, at, 250 * j, 220 * j, 0.14, 0.035, 0.9 * a)
      tone(out, at, 430 * j, 410 * j, 0.09, 0.022, 0.5 * a)
      tone(out, at, 790 * j, 760 * j, 0.05, 0.012, 0.25 * a)
      hiss(out, r, at, 0.014, 2600, 1800, 0.8, 0.3 * a, decay(9))
    }
    return peakTo(out, 0.9)
  },
  /** Steady rain: a soft hiss with single drops in it. Loops for as long as `dur`. */
  rain(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 9)
    const d = o.dur ?? 4
    const out = buf(d)
    hiss(out, r, 0, d, 5200, 5200, 1.5, 0.3, (u) => Math.min(1, u * d * 2) * Math.min(1, (1 - u) * d * 2) * (0.85 + 0.15 * Math.sin(u * d * 1.3)))
    hiss(out, r, 0, d, 1500, 1500, 1.6, 0.1, (u) => Math.min(1, u * d * 2) * Math.min(1, (1 - u) * d * 2))
    const drops = Math.round(d * 14)
    for (let i = 0; i < drops; i++) {
      const at = r() * (d - 0.08)
      const f = 1800 + r() * 3600
      tone(out, at, f, f * 1.25, 0.03, 0.008, 0.1 + r() * 0.16)
    }
    return peakTo(out, 0.7)
  },
  /** A breath of wind that rises and falls. */
  wind(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 11)
    const d = o.dur ?? 4
    const out = buf(d)
    hiss(out, r, 0, d, 380, 380, 0.9, 0.9, (u) => swell(1.4)(u) * (0.7 + 0.3 * Math.sin(u * d * 2.1)))
    hiss(out, r, 0, d, 620, 1300, 0.8, 0.5, (u) => swell(2.2)(u))
    return peakTo(lowpass(out, 3200), 0.7)
  },
  /** Small birds: phrases of two to four quick chirps, scattered over `dur` seconds. */
  birds(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 13)
    const d = o.dur ?? 4
    const out = buf(d)
    let at = 0.15 + r() * 0.5
    while (at < d - 0.6) {
      const base = (2400 + r() * 1900) * (o.pitch ?? 1)
      const notes = 2 + Math.floor(r() * 3)
      const loud = 0.4 + r() * 0.6
      for (let i = 0; i < notes; i++) {
        const up = r() > 0.4
        const f0 = base * (1 + (r() - 0.5) * 0.2)
        const len = 0.05 + r() * 0.06
        tone(out, at, f0, f0 * (up ? 1.35 : 0.78), len, len * 0.7, loud * 0.5, 0.008)
        // the trill that makes it a bird and not a whistle
        tone(out, at + len * 0.3, f0 * 1.5, f0 * (up ? 1.9 : 1.2), len * 0.6, len * 0.4, loud * 0.16, 0.006)
        at += len + 0.03 + r() * 0.05
      }
      at += 0.5 + r() * 1.5
    }
    return peakTo(out, 0.8)
  },
  /** A bee going by: a buzz that wavers, nears and passes. */
  bee(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 15)
    const d = o.dur ?? 2.4
    const out = buf(d)
    let ph = 0
    for (let i = 0; i < out.length; i++) {
      const u = i / out.length
      const f = (205 + 26 * Math.sin(u * d * 9) + 14 * Math.sin(u * d * 23.7) - 18 * u) * (o.pitch ?? 1)
      ph += f / SR
      const p = ph - Math.floor(ph)
      // a buzz is a rough saw; the wing beat pulses it
      const saw = 2 * p - 1 + 0.2 * (r() - 0.5)
      out[i] = saw * swell(1.2)(u) * (0.72 + 0.28 * Math.sin(u * d * 2 * Math.PI * 27))
    }
    return peakTo(lowpass(lowpass(out, 1700), 2600), 0.8)
  },
  /** Something dropping into water: the slap, the hollow gulp, the drops that follow. */
  splash(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 17)
    const out = buf(0.9)
    hiss(out, r, 0, 0.5, 5200, 700, 1.2, 0.9, (u) => Math.min(1, u * 40) * Math.exp(-u * 5))
    tone(out, 0.02, 260, 620, 0.12, 0.05, 0.7, 0.01)
    for (let i = 0; i < 7; i++) {
      const at = 0.16 + r() * 0.6
      const f = 700 + r() * 1500
      tone(out, at, f, f * 1.6, 0.045, 0.014, 0.16 + r() * 0.2, 0.004)
    }
    return peakTo(out, 0.9)
  },
  /** Laughter without a voice: a run of bright little chirps that fall, like a giggle. */
  laugh(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 19)
    const n = o.count ?? 5
    const out = buf(0.13 * n + 0.25)
    const base = 780 * (o.pitch ?? 1)
    for (let i = 0; i < n; i++) {
      const at = i * (0.11 + r() * 0.02)
      const f = base * Math.pow(0.93, i) * (0.97 + r() * 0.06)
      tone(out, at, f * 0.84, f * 1.1, 0.045, 0.05, 0.55 * (1 - i * 0.08), 0.008, 0.3)
      tone(out, at + 0.045, f * 1.1, f * 0.8, 0.05, 0.03, 0.45 * (1 - i * 0.08), 0.004, 0.3)
    }
    return peakTo(out, 0.8)
  },
  /** Hands clapping: `count` claps (default one). */
  clap(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 21)
    const n = o.count ?? 1
    const out = buf(0.26 * n + 0.2)
    for (let i = 0; i < n; i++) {
      const at = i * 0.26 + (r() - 0.5) * 0.02
      for (const dt of [0, 0.008, 0.017]) hiss(out, r, at + dt, 0.11, 1500 + r() * 500, 1100, 0.9, dt === 0.017 ? 1 : 0.5, decay(dt === 0.017 ? 5.5 : 12))
      tone(out, at + 0.015, 190, 140, 0.05, 0.02, 0.3)
    }
    return peakTo(out, 0.9)
  },
  /** Something soft moving fast through the air: a turn, a swing, a page. */
  whoosh(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 23)
    const d = o.dur ?? 0.55
    const out = buf(d)
    hiss(out, r, 0, d * 0.55, 320, 1900, 0.7, 0.9, (u) => Math.pow(u, 1.6))
    hiss(out, r, d * 0.5, d * 0.5, 1900, 420, 0.7, 0.9, (u) => Math.pow(1 - u, 1.5))
    return peakTo(lowpass(out, 5200), 0.8)
  },
  /** A small bell (a shop door, a bicycle, a goat). */
  bell(o: SfxOpts = {}): Float32Array {
    const out = buf(1.6)
    const f = 1320 * (o.pitch ?? 1)
    for (const [m, a, tau] of [[1, 1, 0.5], [2.76, 0.5, 0.3], [5.4, 0.25, 0.16], [8.93, 0.12, 0.08]] as const) if (f * m < 15000) tone(out, 0, f * m, f * m, 1.6, tau, a * 0.5, 0.002)
    return peakTo(out, 0.8)
  },
  /** A soft low thud, like a heartbeat heard close: two beats. `count: 1` gives one. */
  thud(o: SfxOpts = {}): Float32Array {
    const out = buf(0.6)
    const p = o.pitch ?? 1
    tone(out, 0, 68 * p, 46 * p, 0.2, 0.07, 1, 0.012)
    if ((o.count ?? 2) > 1) tone(out, 0.21, 60 * p, 42 * p, 0.2, 0.06, 0.7, 0.012)
    return peakTo(lowpass(out, 400), 0.9)
  },
  /** Something small put down, picked or caught: a soft pop. */
  pop(o: SfxOpts = {}): Float32Array {
    const out = buf(0.25)
    const p = o.pitch ?? 1
    tone(out, 0, 520 * p, 760 * p, 0.12, 0.04, 0.8, 0.004)
    tone(out, 0.05, 780 * p, 900 * p, 0.14, 0.05, 0.4, 0.004)
    return peakTo(out, 0.8)
  },
  /** Leaves or cloth stirring. */
  rustle(o: SfxOpts = {}): Float32Array {
    const r = rng(o.seed ?? 29)
    const d = o.dur ?? 0.7
    const out = buf(d)
    hiss(out, r, 0, d, 4200, 2600, 1.3, 0.8, (u) => swell(1.2)(u) * (r() > 0.4 ? 1 : 0.25))
    return peakTo(out, 0.7)
  },
} satisfies Record<string, (o?: SfxOpts) => Float32Array>
export type SfxName = keyof typeof SFX
export const SFX_NAMES = Object.keys(SFX) as SfxName[]

/** One sound on a film's timeline. */
export type Cue = {
  /** When it starts, seconds from the start of the scene. */
  t: number
  sfx: SfxName
  /** Loudness against the other cues: 1 is an ordinary foreground sound, 0.2 a quiet background. */
  gain?: number
  /** −1 left … 1 right. A sound that moves gives `panTo` as well. */
  pan?: number
  panTo?: number
  opts?: SfxOpts
}
